import{blueCameraKeys}from'./camera-keys.js';
import{sampleObjectMotion}from'../path-motion.js';
import{recordSceneAsset}from'../scene-geometry.js';
import{pose,drawBody,body,align,mv}from'./skin.js';
import{geometryScene,rigMath}from'./render.js';
import{box,ellipsoid,bone}from'../opportunity-rig.js';
const{add}=rigMath;
const clamp=x=>Math.max(0,Math.min(1,x)),smooth=x=>{x=clamp(x);return x*x*(3-2*x)},mix=(a,b,q)=>a+(b-a)*q;
export const refinementDefaults={checkpointRefinementEnabled:true,checkpointRefinementRedYaw:1.5707963267948966,checkpointRefinementCoachYaw:1.5707963267948966,checkpointRefinementBlueYaw:1.5707963267948966,checkpointRefinementBlueCoachYaw:-1.3707963267948966,checkpointRefinementCamera:[0,1,4,0,1,0,1100],checkpointRefinementRedRoot:[-1.166,0,.5],checkpointRefinementCoachRoot:[.85,-.09,-.1],checkpointRefinementBlueRoot:[-.60,0,.3],checkpointRefinementBlueCoachRoot:[.50,-.15,-.6],checkpointRefinementBend:1,checkpointRefinementLight:1};
export function refinementPose(t,f={}){f={...refinementDefaults,...f};const blueShot=t>=898+26/30,u=smooth((t-895)/1.25),v=smooth((t-895.9)/2.9),cam=f.checkpointRefinementCamera,camera={eye:cam.slice(0,3),target:cam.slice(3,6),focal:cam[6]};let red,blue,coach;if(!blueShot){red=pose({root:add(f.checkpointRefinementRedRoot,[.301*(1-u),0,1.4*(1-u)]),yaw:f.checkpointRefinementRedYaw,bend:mix(49,9,u)*f.checkpointRefinementBend,headTilt:mix(0,3,u),seated:true,hipY:mix(.575,.39,u)-.06*Math.sin(Math.PI*u)});const d=smooth((t-898.05)/.816666666667),origin=add(f.checkpointRefinementCoachRoot,[mix(0,.44,v),0,0]);coach=pose({root:origin.map((x,i)=>mix(x,[.62,origin[1],2.5][i],d)),yaw:f.checkpointRefinementCoachYaw,folded:true});}else{camera.eye=[0,.8,3.3];camera.target=[0,1.15,0];camera.focal=1300;const clock=898.866666666667+(t-898.866666666667)*(f.checkpointOrbit??1);let a=blueCameraKeys[0],b=a;for(const k of blueCameraKeys){if(k.time<=clock)a=k;if(k.time>=clock){b=k;break;}b=k;}const q=a===b?0:smooth((clock-a.time)/(b.time-a.time));camera.eye=a.eye.map((x,i)=>mix(x,b.eye[i],q));camera.target=a.target.map((x,i)=>mix(x,b.target[i],q));camera.focal=mix(a.focal,b.focal,q);blue=pose({root:f.checkpointRefinementBlueRoot,yaw:f.checkpointRefinementBlueYaw+.06*Math.sin((t-899)*2)});coach=pose({root:f.checkpointRefinementBlueCoachRoot,yaw:f.checkpointRefinementBlueCoachYaw});}if(f.checkpointCameraKeys?.length){let a=f.checkpointCameraKeys[0],b=a;for(const k of f.checkpointCameraKeys){if(k.time<=t)a=k;if(k.time>=t){b=k;break;}b=k;}const q=a===b?0:smooth((t-a.time)/(b.time-a.time));camera.eye=a.eye.map((x,i)=>mix(x,b.eye[i],q));camera.target=a.target.map((x,i)=>mix(x,b.target[i],q));camera.focal=mix(a.focal,b.focal,q);}for(const[name,p]of Object.entries({red,blue,coach}))if(p)editPose(p,f,name,t);return{camera,red,blue,coach,blueShot};}
function tube(scene,points,r,color){const rings=points.map((p,i)=>{const axis=rigMath.unit(rigMath.sub(points[Math.min(i+1,points.length-1)],points[Math.max(0,i-1)])),u=rigMath.unit(rigMath.cross(axis,[1,0,0])),v=rigMath.cross(axis,u);return Array.from({length:12},(_,j)=>{const a=j*Math.PI/6,n=rigMath.add(rigMath.mul(u,Math.cos(a)),rigMath.mul(v,Math.sin(a)));return{p:add(p,rigMath.mul(n,r)),n};});});for(let i=1;i<rings.length;i++)for(let j=0;j<12;j++){const a=rings[i-1][j],b=rings[i][j],cc=rings[i][(j+1)%12],d=rings[i-1][(j+1)%12];scene.triangle(a.p,b.p,d.p,color,[a.n,b.n,d.n]);scene.triangle(b.p,cc.p,d.p,color,[b.n,cc.n,d.n]);}}
function chair(scene,root){const tr=([x,y,z])=>add(root,[z,y,-x]);box(scene,tr([0,.37,0]),[.44,.10,.47],'#242124');box(scene,tr([0,.65,-.21]),[.09,.57,.46],'#292629');for(const s of[-1,1]){const points=[];for(let i=0;i<=15;i++){const a=Math.PI*i/15;points.push(tr([s*.26,.35+.25*Math.sin(a),-.22+.46*i/15]));}tube(scene,points,.018,'#8b8c86');for(const z of[-.18,.18])tube(scene,[tr([s*.20,.04,z]),tr([s*.20,.37,z])],.014,'#7e807a');}}
function cylinder(scene,center,rx,rz,height,color){for(let j=0;j<48;j++){const a=j*Math.PI/24,b=(j+1)*Math.PI/24,pts=[[-1,a],[1,a],[1,b],[-1,b]].map(([s,t])=>add(center,[rx*Math.cos(t),s*height/2,rz*Math.sin(t)])),ns=[a,a,b,b].map(t=>rigMath.unit([Math.cos(t)/rx,0,Math.sin(t)/rz]));scene.triangle(pts[0],pts[1],pts[3],color,[ns[0],ns[1],ns[3]]);scene.triangle(pts[1],pts[2],pts[3],color,[ns[1],ns[2],ns[3]]);for(const s of[-1,1]){const c=add(center,[0,s*height/2,0]),p=add(c,[rx*Math.cos(a),0,rz*Math.sin(a)]),q=add(c,[rx*Math.cos(b),0,rz*Math.sin(b)]);if(s>0)scene.triangle(c,q,p,color);else scene.triangle(c,p,q,color);}}}
function hat(scene,p,color){const h=p.named.head;cylinder(scene,add(h,[0,.135,0]),.167,.145,.018,color);cylinder(scene,add(h,[0,.205,0]),.103,.094,.132,color);cylinder(scene,add(h,[0,.15,0]),.105,.096,.025,'#b2ad96');}
let fog;
function smoke(c,t,strength){fog??=Object.assign(document.createElement('canvas'),{width:240,height:135});const sc=fog.getContext('2d'),im=sc.createImageData(240,135);for(let y=0;y<135;y++)for(let x=0;x<240;x++){const u=y/135,center=65+Math.sin(u*7+t*.45)*18+Math.sin(u*17-t*.36)*8,w=22+u*24,dx=(x-center)/w,n=.5+.22*Math.sin(x*.14+y*.18+t*.6+Math.sin(y*.12)*3)+.15*Math.sin(x*.37-y*.21-t*.4),a=Math.exp(-dx*dx)*Math.sin(Math.PI*u)*Math.max(0,n-.28)*strength,k=(y*240+x)*4;im.data[k]=im.data[k+1]=im.data[k+2]=175;im.data[k+3]=a*170;}sc.putImageData(im,0,0);c.save();c.globalCompositeOperation='screen';c.filter='blur(2px)';c.drawImage(fog,0,-30,960,590);c.restore();}
export function paintRefinement(c,t,input={}){const f={...refinementDefaults,...input},p=refinementPose(t,f),v=smooth((t-895.9)/2.9);c.save();c.translate(480-(f.checkpointCameraX||0),270-(f.checkpointCameraY||0));c.scale(1+(f.checkpointCameraZoom||0),1+(f.checkpointCameraZoom||0));c.translate(-480,-270);const bg=c.createLinearGradient(0,0,0,540);const blueFade=p.blueShot?smooth((t-898.866666666667)/.65):0,blend=(a,b)=>'#'+a.map((v,i)=>Math.round(mix(v,b[i],blueFade)).toString(16).padStart(2,'0')).join('');bg.addColorStop(0,blend([22,3,4],[7,6,12]));bg.addColorStop(1,blend([48,4,7],[38,33,55]));c.fillStyle=bg;c.fillRect(0,0,960,540);if(!p.blueShot&&f.checkpointLayerEdits?.smoke?.visible!==false)smoke(c,t,f.checkpointSmoke??1);const scene=geometryScene(p.camera,{ambient:p.blueShot?.35:.015,power:(p.blueShot?1.0:.55)*f.checkpointRefinementLight,key:p.blueShot?[.6,1,1]:[1,.4,.7],rim:[1,.3,-.6],rimColor:p.blueShot?[.65,.7,1]:[1,.05,.015],rimPower:p.blueShot?.6:1.4,specular:p.blueShot?.65:.25});
const visible=id=>f.checkpointLayerEdits?.[id]?.visible!==false;const object=(id,draw)=>{if(!visible(id))return;const n=scene.commands.length,e=f.checkpointLayerEdits?.[id]||{},m=sampleObjectMotion((t-895)/(f.checkpointRate||1),e.motion||{});draw();for(const cmd of scene.commands.slice(n))cmd.edit={id,x:(e.x||0)+m.x,y:(e.y||0)+m.y,scale:(e.scale??1)*m.scale,rotation:(e.rotation||0)+m.rotation,opacity:(e.opacity??1)*m.opacity,blur:e.blur||0};};
if(!p.blueShot){object('chair',()=>chair(scene,add(f.checkpointRefinementRedRoot,[-.03,0,0])));object('red-figure',()=>drawBody(scene,p.red,f.checkpointRed||'#cb2218'));object('desk',()=>{box(scene,[.35-.48*v,.29,.16],[1.79,.58,.075],'#020202');box(scene,[.35-.48*v,.59,0],[1.80,.015,.40],'#e8e8e5');});}
else object('blue-figure',()=>drawBody(scene,p.blue,f.checkpointBlue==='#164a9c'?'#188bd0':f.checkpointBlue||'#188bd0'));object('coach',()=>{drawBody(scene,p.coach,f.checkpointCream==='#d8d6bb'?'#eeeedd':f.checkpointCream||'#eeeedd');hat(scene,p.coach,'#eeeedd');});scene.paint(c);for(const[id,actor]of[['red-figure',p.red],['blue-figure',p.blue],['coach',p.coach]])if(actor&&visible(id)){const pts=actor.joints.map(scene.project),x=Math.min(...pts.map(p=>p.x))-20,y=Math.min(...pts.map(p=>p.y))-30;recordSceneAsset(c,{id:'checkpoint:'+id,editKey:id,name:id,kind:'checkpoint'},[x,y,Math.max(...pts.map(p=>p.x))-x+20,Math.max(...pts.map(p=>p.y))-y+30]);}
if(!p.blueShot&&t>898.3&&f.checkpointFocusStrength!==0){/* Source blur is kept as a separate editable overlay in the host. */}
c.restore();return p;}

function editPose(p,f,name,t){const before=p.joints.map(a=>a.slice());for(let i=0;i<body.joints.length;i++){const key=body.joints[i],offset=f.checkpointJointOffsets?.[name]?.[key];if(offset)p.joints[i]=add(p.joints[i],offset);const keys=f.checkpointJointKeys?.[name]?.[key];if(keys?.length){let a=keys[0],b=a;for(const k of keys){if(k.time<=t)a=k;if(k.time>=t){b=k;break;}b=k;}const q=a===b?0:a.ease==='linear'?clamp((t-a.time)/(b.time-a.time)):smooth((t-a.time)/(b.time-a.time));p.joints[i]=a.position.map((v,k)=>mix(v,b.position[k],q));}p.named[key]=p.joints[i];}for(let i=1;i<body.joints.length;i++){const par=body.parents[i],R=align(rigMath.sub(before[i],before[par]),rigMath.sub(p.joints[i],p.joints[par])),old=p.rotations[i];p.rotations[i]=Array.from({length:9},(_,k)=>R[Math.floor(k/3)*3]*old[k%3]+R[Math.floor(k/3)*3+1]*old[k%3+3]+R[Math.floor(k/3)*3+2]*old[k%3+6]);}}
